nd":"r","name":"owner_review_evidence_select","permissive":true,"roles":["authenticated"],"using":"(EXISTS ( SELECT 1\n   FROM snap_relaunch.owner_review_access a\n  WHERE ((a.preparation_sha256 = parcel_evidence.preparation_sha256) AND (a.reviewer_user_id = ( SELECT auth.uid() AS uid)) AND a.enabled AND (a.revoked_at IS NULL))))"}],"rls":true,"table":"snap_relaunch.parcel_evidence","triggers":[{"definition":"CREATE TRIGGER parcel_evidence_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON snap_relaunch.parcel_evidence FOR EACH STATEMENT EXECUTE FUNCTION snap_relaunch.reject_intake_mutation()","enabled":"O","name":"parcel_evidence_immutable"}]},{"acl":"{postgres=arwdDxtm/postgres}","force_rls":false,"owner":"postgres","policies":[{"check":null,"command":"r","name":"owner_review_identity_select","permissive":true,"roles":["authenticated"],"using":"(EXISTS ( SELECT 1\n   FROM snap_relaunch.parcel_evidence pe\n  WHERE ((pe.property_id = property_identities.property_id) AND (pe.source_parcel_reference = property_identities.source_parcel_reference))))"}],"rls":true,"table":"snap_relaunch.property_identities","triggers":[{"definition":"CREATE TRIGGER property_identities_immutable BEFORE DELETE OR UPDATE OR TRUNCATE ON snap_relaunch.property_identities FOR EACH STATEMENT EXECUTE FUNCTION snap_relaunch.reject_intake_mutation()","enabled":"O","name":"property_identities_immutable"}]},{"acl":"{postgres=arwdDxtm/postgres}","force_rls":false,"owner":"postgres","policies":[],"rls":true,"table":"snap_relaunch.source_crm_links","triggers":[{"definition":"CREATE TRIGGER source_decision_append_only BEFORE DELETE OR UPDATE OR TRUNCATE ON snap_relaunch.source_crm_links FOR EACH STATEMENT EXECUTE FUNCTION snap_relaunch.reject_intake_mutation()","enabled":"O","name":"source_decision_append_only"}]},{"acl":"{postgres=arwdDxtm/postgres}","force_rls":false,"owner":"postgres","policies":[],"rls":true,"table":"snap_relaunch.source_management_acceptance_bindings_v1","triggers":[{"definition":"CREATE TRIGGER source_management_append_only BEFORE DELETE OR UPDATE OR TRUNCATE ON snap_relaunch.source_management_acceptance_bindings_v1 FOR EACH STATEMENT EXECUTE FUNCTION snap_relaunch.reject_intake_mutation()","enabled":"O","name":"source_management_append_only"}]},{"acl":"{postgres=arwdDxtm/postgres}","force_rls":false,"owner":"postgres","policies":[],"rls":true,"table":"snap_relaunch.source_management_grants_v1","triggers":[{"definition":"CREATE TRIGGER source_management_append_only BEFORE DELETE OR UPDATE OR TRUNCATE ON snap_relaunch.source_management_grants_v1 FOR EACH STATEMENT EXECUTE FUNCTION snap_relaunch.reject_intake_mutation()","enabled":"O","name":"source_management_append_only"},{"definition":"CREATE TRIGGER source_management_insert_guard BEFORE INSERT ON snap_relaunch.source_management_grants_v1 FOR EACH ROW EXECUTE FUNCTION snap_relaunch.guard_source_management_insert_v1()","enabled":"O","name":"source_management_insert_guard"}]},{"acl":"{postgres=arwdDxtm/postgres}","force_rls":false,"owner":"postgres","policies":[],"rls":true,"table":"snap_relaunch.source_management_revocations_v1","triggers":[{"definition":"CREATE TRIGGER source_management_append_only BEFORE DELETE OR UPDATE OR TRUNCATE ON snap_relaunch.source_management_revocations_v1 FOR EACH STATEMENT EXECUTE FUNCTION snap_relaunch.reject_intake_mutation()","enabled":"O","name":"source_management_append_only"},{"definition":"CREATE TRIGGER source_management_insert_guard BEFORE INSERT ON snap_relaunch.source_management_revocations_v1 FOR EACH ROW EXECUTE FUNCTION snap_relaunch.guard_source_management_insert_v1()","enabled":"O","name":"source_management_insert_guard"}]},{"acl":"{postgres=arwdDxtm/postgres}","force_rls":false,"owner":"postgres","policies":[],"rls":true,"table":"snap_relaunch.source_review_events","triggers":[{"definition":"CREATE TRIGGER source_decision_append_only BEFORE DELETE OR UPDATE OR TRUNCATE ON snap_relaunch.source_review_events FOR EACH STATEMENT EXECUTE FUNCTION snap_relaunch.reject_intake_mutation()","enabled":"O","name":"source_decision_append_only"}]},{"acl":"{postgres=arwdDxtm/postgres}","force_rls":false,"owner":"postgres","policies":[],"rls":true,"table":"snap_relaunch.source_revocations","triggers":[{"definition":"CREATE TRIGGER source_decision_append_only BEFORE DELETE OR UPDATE OR TRUNCATE ON snap_relaunch.source_revocations FOR EACH STATEMENT EXECUTE FUNCTION snap_relaunch.reject_intake_mutation()","enabled":"O","name":"source_decision_append_only"}]}]}'::jsonb THEN RAISE EXCEPTION 'source_consumer_before_catalog_drift';END IF;
 snapshot:='{}'::jsonb;FOR t IN SELECT unnest(ARRAY['public.credit_ledger','public.lead_activities','public.leads','public.pipeline_stages','public.profiles','public.properties','public.subscription_plans','public.unlocked_properties','public.user_subscriptions','snap_relaunch.customer_property_mappings','snap_relaunch.customer_source_acceptances','snap_relaunch.intake_batches','snap_relaunch.intake_events','snap_relaunch.intake_parcels','snap_relaunch.owner_review_access','snap_relaunch.parcel_evidence','snap_relaunch.property_identities','snap_relaunch.source_crm_links','snap_relaunch.source_management_acceptance_bindings_v1','snap_relaunch.source_management_grants_v1','snap_relaunch.source_management_revocations_v1','snap_relaunch.source_review_events','snap_relaunch.source_revocations']) LOOP EXECUTE format('SELECT count(*) FROM %s',t) INTO n;snapshot:=snapshot||jsonb_build_object(t,n);END LOOP;
 PERFORM set_config('snap.source_consumer_counts',snapshot::text,true);
 END $before$;
-- BEGIN EXACT CORE
SET LOCAL lock_timeout='5s';
SET LOCAL statement_timeout='30s';
SET LOCAL search_path=pg_catalog;
DO $guard$ BEGIN
 IF current_user<>'postgres' THEN RAISE EXCEPTION 'Reviewed database administration required';END IF;
 IF to_regprocedure('snap_relaunch.source_self_consumer_eligible_v1(uuid)') IS NOT NULL THEN RAISE EXCEPTION 'Source consumer correction already exists';END IF;
 IF md5(pg_get_functiondef(to_regprocedure('snap_relaunch.require_source_acceptance_v1(uuid,text)'))) IS DISTINCT FROM '6d54e7ad0f6be5d6b4313bffcd006426' THEN RAISE EXCEPTION 'Source consumer baseline drift: snap_relaunch.require_source_acceptance_v1(uuid,text)';END IF;
 IF md5(pg_get_functiondef(to_regprocedure('snap_relaunch.owner_source_acceptance_status_v1(text,uuid)'))) IS DISTINCT FROM '569cc1e6d65cc9b594b9de68f02e1845' THEN RAISE EXCEPTION 'Source consumer baseline drift: snap_relaunch.owner_source_acceptance_status_v1(text,uuid)';END IF;
 IF md5(pg_get_functiondef(to_regprocedure('public.fn_unlock_property(uuid,uuid)'))) IS DISTINCT FROM 'dc9e632ff4d616787d308a34988fd571' THEN RAISE EXCEPTION 'Source consumer baseline drift: public.fn_unlock_property(uuid,uuid)';END IF;
 IF md5(pg_get_functiondef(to_regprocedure('public.fn_reserve_source_export_v1(uuid,uuid)'))) IS DISTINCT FROM 'cdc265e0a78a712007f4328875ae49ca' THEN RAISE EXCEPTION 'Source consumer baseline drift: public.fn_reserve_source_export_v1(uuid,uuid)';END IF;
 IF md5(pg_get_functiondef(to_regprocedure('snap_relaunch.source_management_current_grant_v1(text,uuid)'))) IS DISTINCT FROM 'a9828bdca7a518b1c79880780c60ed2a' THEN RAISE EXCEPTION 'Source consumer baseline drift: snap_relaunch.source_management_current_grant_v1(text,uuid)';END IF;
 IF md5(pg_get_functiondef(to_regprocedure('snap_relaunch.source_accepting_authority_current_v1(uuid)'))) IS DISTINCT FROM '741c0bb879ab20a7c940e7a950bebb2e' THEN RAISE EXCEPTION 'Source consumer baseline drift: snap_relaunch.source_accepting_authority_current_v1(uuid)';END IF;
END $guard$;
CREATE FUNCTION snap_relaunch.source_self_consumer_eligible_v1(p_acceptance uuid)
RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog AS $$
 SELECT coalesce(a.actor_user_id=a.consumer_user_id
  AND a.purpose IN ('customer_export','crm') AND a.scope='dated_parcel_source_snapshot'
  AND cardinality(a.mapping_ids)>0
  AND EXISTS(SELECT 1 FROM snap_relaunch.source_management_acceptance_bindings_v1 b
    WHERE b.acceptance_id=a.id AND b.grant_id=snap_relaunch.source_management_current_grant_v1(a.preparation_sha256,a.consumer_user_id))
  AND NOT EXISTS(SELECT 1 FROM unnest(a.mapping_ids) mid
    LEFT JOIN snap_relaunch.customer_property_mappings m ON m.id=mid
    WHERE m.id IS NULL OR NOT m.created_for_source OR m.preparation_sha256<>a.preparation_sha256),false)
 FROM snap_relaunch.customer_source_acceptances a WHERE a.id=p_acceptance
$$;
-- Eligibility only. Callers must also run require_source_acceptance_v1 for
-- current review, exact evidence, expiry/revocations, account and organization.
REVOKE ALL ON FUNCTION snap_relaunch.source_self_consumer_eligible_v1(uuid) FROM PUBLIC,anon,authenticated,service_role;
DO $acl$ DECLARE g record;role_name text;BEGIN
 FOR g IN SELECT a.grantee FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a
  WHERE p.oid='snap_relaunch.source_self_consumer_eligible_v1(uuid)'::regprocedure AND a.grantee<>p.proowner LOOP
  role_name:=CASE WHEN g.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(g.grantee)) END;
  EXECUTE format('REVOKE ALL ON FUNCTION snap_relaunch.source_self_consumer_eligible_v1(uuid) FROM %s',role_name);
 END LOOP;
END $acl$;

CREATE OR REPLACE FUNCTION snap_relaunch.require_source_acceptance_v1(p_acceptance uuid, p_purpose text)
 RETURNS snap_relaunch.customer_source_acceptances
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a snap_relaunch.customer_source_acceptances%ROWTYPE;BEGIN
 IF auth.uid() IS NULL THEN
  RAISE EXCEPTION 'Customer access remains held' USING ERRCODE='42501';END IF;
 SELECT * INTO a FROM snap_relaunch.customer_source_acceptances WHERE id=p_acceptance AND consumer_user_id=auth.uid() AND purpose=p_purpose;
 IF NOT FOUND OR (NOT coalesce(public.has_role(auth.uid(),'admin'::public.app_role),false)
  AND NOT coalesce(snap_relaunch.source_self_consumer_eligible_v1(a.id),false)) THEN
  RAISE EXCEPTION 'Customer access remains held' USING ERRCODE='42501';END IF;
 IF NOT FOUND OR a.valid_until<=clock_timestamp() OR EXISTS(SELECT 1 FROM snap_relaunch.source_revocations r WHERE r.kind='acceptance' AND r.target_id=a.id)
  OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=auth.uid() AND org_id=a.consumer_org_id)
  OR NOT EXISTS(SELECT 1 FROM auth.users WHERE id=auth.uid() AND deleted_at IS NULL AND confirmed_at IS NOT NULL
    AND NOT coalesce(is_anonymous,false) AND (banned_until IS NULL OR banned_until<=now()))
  OR EXISTS(SELECT 1 FROM snap_relaunch.source_revocations r WHERE r.kind='mapping' AND r.target_id=ANY(a.mapping_ids))
  OR EXISTS(SELECT 1 FROM snap_relaunch.customer_property_mappings m JOIN public.properties p ON p.id=m.customer_property_id
    WHERE m.id=ANY(a.mapping_ids) AND snap_relaunch.source_hash_v1(to_jsonb(p))<>m.target_snapshot_sha256)
  OR EXISTS(SELECT 1 FROM snap_relaunch.source_review_events r WHERE r.preparation_sha256=a.preparation_sha256
    AND r.outcome IN ('held','rejected') AND r.record_keys&&a.record_keys AND r.created_at>a.created_at)
  OR NOT snap_relaunch.source_accepting_authority_current_v1(a.id)
  OR NOT snap_relaunch.source_authorization_current_v1(a.preparation_sha256,a.actor_user_id,true)
  OR NOT snap_relaunch.source_authorization_current_v1(a.preparation_sha256,
    (SELECT reviewer_user_id FROM snap_relaunch.source_review_events WHERE id=a.review_event_id),false)
  OR a.review_event_id IS DISTINCT FROM (SELECT id FROM snap_relaunch.source_review_events WHERE preparation_sha256=a.preparation_sha256
    AND selection_sha256=a.selection_sha256 ORDER BY created_at DESC,id DESC LIMIT 1) THEN
  RAISE EXCEPTION 'Current source acceptance unavailable' USING ERRCODE='42501';END IF;
 IF snap_relaunch.source_hash_v1(snap_relaunch.source_manifest_v1(a.preparation_sha256,a.record_keys))<>a.selection_sha256 THEN
  RAISE EXCEPTION 'Accepted source evidence changed' USING ERRCODE='42501';END IF;
 RETURN a;
END $function$
;
CREATE OR REPLACE FUNCTION snap_relaunch.owner_source_acceptance_status_v1(p_preparation text, p_acceptance uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a snap_relaunch.customer_source_acceptances%ROWTYPE;reason text;BEGIN
 SELECT * INTO a FROM snap_relaunch.customer_source_acceptances WHERE id=p_acceptance AND preparation_sha256=p_preparation;
 IF NOT FOUND THEN RAISE EXCEPTION 'Source acceptance unavailable' USING ERRCODE='42501';END IF;
 IF a.valid_until<=clock_timestamp() THEN reason:='acceptance_expired';
 ELSIF EXISTS(SELECT 1 FROM snap_relaunch.source_revocations WHERE kind='acceptance' AND target_id=a.id) THEN reason:='acceptance_revoked';
 ELSIF NOT coalesce(public.has_role(a.consumer_user_id,'admin'::public.app_role),false)
  AND NOT coalesce(snap_relaunch.source_self_consumer_eligible_v1(a.id),false) THEN reason:='customer_access_held';
 ELSIF NOT EXISTS(SELECT 1 FROM auth.users WHERE id=a.consumer_user_id AND deleted_at IS NULL AND confirmed_at IS NOT NULL
  AND NOT coalesce(is_anonymous,false) AND (banned_until IS NULL OR banned_until<=now())) THEN reason:='consumer_account_unavailable';
 ELSIF NOT EXISTS(SELECT 1 FROM public.profiles WHERE user_id=a.consumer_user_id AND org_id=a.consumer_org_id) THEN reason:='consumer_organization_changed';
 ELSIF EXISTS(SELECT 1 FROM snap_relaunch.source_revocations WHERE kind='mapping' AND target_id=ANY(a.mapping_ids)) THEN reason:='mapping_revoked';
 ELSIF EXISTS(SELECT 1 FROM snap_relaunch.customer_property_mappings m JOIN public.properties p ON p.id=m.customer_property_id
  WHERE m.id=ANY(a.mapping_ids) AND snap_relaunch.source_hash_v1(to_jsonb(p))<>m.target_snapshot_sha256) THEN reason:='mapping_target_changed';
 ELSIF NOT snap_relaunch.source_accepting_authority_current_v1(a.id) THEN reason:='accepting_grant_unavailable';
 ELSIF NOT snap_relaunch.source_authorization_current_v1(a.preparation_sha256,a.actor_user_id,true) THEN reason:='accepting_owner_unavailable';
 ELSIF NOT snap_relaunch.source_authorization_current_v1(a.preparation_sha256,
  (SELECT reviewer_user_id FROM snap_relaunch.source_review_events WHERE id=a.review_event_id),false) THEN reason:='original_reviewer_unavailable';
 ELSIF a.review_event_id IS DISTINCT FROM (SELECT id FROM snap_relaunch.source_review_events WHERE preparation_sha256=a.preparation_sha256
  AND selection_sha256=a.selection_sha256 ORDER BY created_at DESC,id DESC LIMIT 1) THEN reason:='review_superseded';
 ELSIF EXISTS(SELECT 1 FROM snap_relaunch.source_review_events r WHERE r.preparation_sha256=a.preparation_sha256
  AND r.outcome IN ('held','rejected') AND r.record_keys&&a.record_keys AND r.created_at>a.created_at) THEN reason:='later_review_holds_records';
 ELSE
  BEGIN
   IF snap_relaunch.source_hash_v1(snap_relaunch.source_manifest_v1(a.preparation_sha256,a.record_keys))<>a.selection_sha256 THEN reason:='source_evidence_changed';END IF;
  EXCEPTION WHEN SQLSTATE '42501' OR SQLSTATE '22023' THEN reason:='source_evidence_changed';END;
 END IF;
 RETURN jsonb_build_object('current',reason IS NULL,'unavailable_reason',reason);
END $function$
;
CREATE OR REPLACE FUNCTION public.fn_unlock_property(p_user_id uuid, p_property_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sub public.user_subscriptions%ROWTYPE;
  v_has_subscription boolean;
  v_free_remaining integer;
  v_plan_max integer;
  v_new_exports integer;
  v_credit_balance integer;
  v_trial_result jsonb;
  v_limited_source boolean := false;
BEGIN
  IF auth.uid() IS NULL OR p_user_id IS DISTINCT FROM auth.uid() THEN
    RETURN jsonb_build_object('success',false,'error','unauthorized');
  END IF;
  -- Nonadmin eligibility is checked below, after the shared wallet lock.
  -- General property RLS stays closed; only an exact self-accepted source may unlock.
  v_limited_source := NOT COALESCE(public.has_role(auth.uid(),'admin'::public.app_role),false);
  IF p_property_id IS NULL THEN
    RETURN jsonb_build_object('success',false,'error','property_unavailable');
  END IF;

  -- Serializes direct unlock attempts for this account, including duplicate
  -- properties and competing free credits. No mutable client balance is used.
  SELECT free_unlocks_remaining INTO v_free_remaining FROM public.profiles
  WHERE user_id = auth.uid() FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success',false,'error','account_unavailable');
  END IF;
  IF v_limited_source THEN
    -- Match export lock order: profile first, then current source grant lock.
    -- Acquire before loading immutable decisions so the next READ COMMITTED
    -- statement also observes mapping/acceptance revocations committed in the wait.
    PERFORM pg_advisory_xact_lock(810207,71);
    -- A CRM-only acceptance never confers export or unlock authority.
    IF NOT public.fn_is_source_property_v1(p_property_id) THEN
      RETURN jsonb_build_object('success',false,'error','customer_access_held');
    END IF;
    DECLARE authorized boolean := false; candidate record;
    BEGIN
      FOR candidate IN SELECT DISTINCT a.id FROM snap_relaunch.customer_source_acceptances a
        JOIN snap_relaunch.customer_property_mappings m ON m.id=ANY(a.mapping_ids)
        WHERE a.consumer_user_id=auth.uid() AND a.actor_user_id=auth.uid()
          AND a.purpose='customer_export' AND m.customer_property_id=p_property_id AND m.created_for_source LOOP
        BEGIN
          PERFORM snap_relaunch.require_source_acceptance_v1(candidate.id,'customer_export');
          IF coalesce(snap_relaunch.source_self_consumer_eligible_v1(candidate.id),false) THEN
            authorized:=true;EXIT;
          END IF;
        EXCEPTION WHEN SQLSTATE '42501' THEN NULL;
        END;
      END LOOP;
      IF NOT authorized THEN RETURN jsonb_build_object('success',false,'error','customer_access_held');END IF;
    END;
  END IF;
  SELECT * INTO v_sub FROM public.user_subscriptions
  WHERE user_id = auth.uid() ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
  v_has_subscription := FOUND;
  IF v_has_subscription THEN
    IF v_sub.status IN ('trial','trialing') THEN
      IF v_sub.trial_started_at IS NULL OR v_sub.trial_started_at > now() OR
         v_sub.trial_ends_at IS NULL OR v_sub.trial_ends_at <= now() THEN
        RETURN jsonb_build_object('success',false,'error','trial_expired');
      END IF;
    ELSIF v_sub.status IN ('active','past_due') THEN
      IF v_sub.current_period_start IS NULL OR v_sub.current_period_start > now() OR
         v_sub.current_period_end IS NULL OR v_sub.current_period_end <= now() THEN
        RETURN jsonb_build_object('success',false,'error','subscription_expired');
      END IF;
    ELSE
      RETURN jsonb_build_object('success',false,'error','subscription_expired');
    END IF;
  END IF;

  IF NOT public.fn_source_property_visible_v1(p_property_id) OR NOT EXISTS(SELECT 1 FROM public.properties WHERE id=p_property_id) THEN
    RETURN jsonb_build_object('success',false,'error','property_unavailable');
  END IF;
  IF EXISTS(SELECT 1 FROM public.unlocked_properties WHERE user_id=auth.uid() AND property_id=p_property_id) THEN
    RETURN jsonb_build_object('success',true,'source','already_unlocked','message','Property already unlocked');
  END IF;

  IF NOT v_limited_source AND v_has_subscription AND v_sub.status IN ('trial','trialing') THEN
    v_trial_result := public.fn_increment_trial_exports(auth.uid(),1);
    IF (v_trial_result->>'success')::boolean IS DISTINCT FROM true THEN
      RETURN v_trial_result;
    END IF;
    INSERT INTO public.unlocked_properties(user_id,property_id,credit_cost,unlock_source)
    VALUES(auth.uid(),p_property_id,0,'subscription');
    RETURN jsonb_build_object('success',true,'source','trial_allowance',
      'subscription_remaining',v_trial_result->'remaining','free_remaining',v_free_remaining);
  END IF;

  IF NOT v_limited_source AND v_has_subscription THEN
    SELECT max_monthly_exports INTO v_plan_max FROM public.subscription_plans WHERE id=v_sub.plan_id;
    IF v_plan_max IS NULL OR v_plan_max < -1 THEN
      RETURN jsonb_build_object('success',false,'error','subscription_quota_invalid');
    END IF;
    INSERT INTO public.subscription_usage(user_id,period_start,period_end)
    VALUES(auth.uid(),v_sub.current_period_start::date,v_sub.current_period_end::date)
    ON CONFLICT(user_id,period_start) DO NOTHING;
    UPDATE public.subscription_usage SET exports_count=exports_count+1,updated_at=now()
    WHERE user_id=auth.uid() AND period_start=v_sub.current_period_start::date
      AND exports_count>=0 AND (v_plan_max=-1 OR exports_count<v_plan_max)
    RETURNING exports_count INTO v_new_exports;
    IF FOUND THEN
      INSERT INTO public.unlocked_properties(user_id,property_id,credit_cost,unlock_source)
      VALUES(auth.uid(),p_property_id,0,'subscription');
      RETURN jsonb_build_object('success',true,'source','subscription_allowance',
        'subscription_remaining',CASE WHEN v_plan_max=-1 THEN NULL ELSE v_plan_max-v_new_exports END,
        'free_remaining',v_free_remaining);
    END IF;
  END IF;

  UPDATE public.profiles SET free_unlocks_remaining=free_unlocks_remaining-1
  WHERE user_id=auth.uid() AND free_unlocks_remaining>0 RETURNING free_unlocks_remaining INTO v_free_remaining;
  IF FOUND THEN
    INSERT INTO public.unlocked_properties(user_id,property_id,credit_cost,unlock_source)
    VALUES(auth.uid(),p_property_id,0,'free_credit');
    RETURN jsonb_build_object('success',true,'source','free_credit','free_remaining',v_free_remaining);
  END IF;

  IF v_limited_source THEN
    RETURN jsonb_build_object('success',false,'error','free_source_allowance_exhausted',
      'message','This limited source proof requires an existing free unlock. No paid credits were used.');
  END IF;

  SELECT COALESCE(balance,0) INTO v_credit_balance FROM public.v_user_credits WHERE user_id=auth.uid();
  IF COALESCE(v_credit_balance,0)>0 THEN
    INSERT INTO public.credit_ledger(user_id,delta,reason,meta)
    VALUES(auth.uid(),-1,'property_unlock',jsonb_build_object('job_id',p_property_id,'property_id',p_property_id,'version','wallet-v1'));
    INSERT INTO public.unlocked_properties(user_id,property_id,credit_cost,unlock_source)
    VALUES(auth.uid(),p_property_id,1,'credit_pack');
    RETURN jsonb_build_object('success',true,'source','credit_pack','credits_remaining',v_credit_balance-1,'free_remaining',COALESCE(v_free_remaining,0));
  END IF;
  RETURN jsonb_build_object('success',false,'error','insufficient_balance',
    'free_remaining',COALESCE(v_free_remaining,0),'credits',COALESCE(v_credit_balance,0),
    'message','Property access could not be authorized with the current allowance.');
END;
$function$
;
CREATE OR REPLACE FUNCTION public.fn_reserve_source_export_v1(p_request_id uuid, p_acceptance_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
DECLARE a snap_relaunch.customer_source_acceptances%ROWTYPE;s public.user_subscriptions%ROWTYPE;
 prior public.export_logs%ROWTYPE;has_sub boolean;mode text;tier text;ids uuid[];rows jsonb;n integer;
 req_hash text;selection_hash text;result jsonb;entitlement jsonb;unlocks jsonb:='[]'::jsonb;pid uuid;
BEGIN
 IF auth.uid() IS NULL OR p_request_id IS NULL OR p_acceptance_id IS NULL THEN
  RAISE EXCEPTION 'Authenticated export identity required' USING ERRCODE='42501';END IF;
 -- Same first lock as every wallet debit and the current legacy export path.
 PERFORM 1 FROM public.profiles WHERE user_id=auth.uid() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Export account unavailable' USING ERRCODE='42501';END IF;
 PERFORM pg_advisory_xact_lock(810207,71);
 a:=snap_relaunch.require_source_acceptance_v1(p_acceptance_id,'customer_export');
 SELECT * INTO s FROM public.user_subscriptions WHERE user_id=auth.uid() ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
 has_sub:=FOUND;
 IF has_sub THEN
  IF s.status IN ('trial','trialing') THEN
   mode:='trial';
   IF s.trial_started_at IS NULL OR s.trial_started_at>now() OR s.trial_ends_at IS NULL OR s.trial_ends_at<=now() THEN
    RAISE EXCEPTION 'Trial expired or unverified' USING ERRCODE='42501';END IF;
  ELSIF s.status='active' THEN
   mode:='subscription';
   IF s.current_period_start IS NULL OR s.current_period_start>now() OR s.current_period_end IS NULL OR s.current_period_end<=now() THEN
    RAISE EXCEPTION 'Subscription expired or unverified' USING ERRCODE='42501';END IF;
  ELSE RAISE EXCEPTION 'No current subscription authorization' USING ERRCODE='42501';END IF;
  SELECT data_tier INTO tier FROM public.subscription_plans WHERE id=s.plan_id;
  IF tier IS NULL OR tier NOT IN ('basic','premium') THEN RAISE EXCEPTION 'Subscription tier unverified' USING ERRCODE='42501';END IF;
 ELSE mode:='payg';END IF;
 -- A limited self-source acceptance never authorizes subscription/trial spending.
 -- Dates and tier above remain checked; the existing wallet branch below then
 -- enforces free-only allowance under the same profile/source locks.
 IF NOT coalesce(public.has_role(auth.uid(),'admin'::public.app_role),false) THEN
  mode:='payg';
 END IF;
 req_hash:=snap_relaunch.source_hash_v1(jsonb_build_array('source-event-export-v1',a.id,a.command_sha256));
 selection_hash:=snap_relaunch.source_hash_v1(a.mapped_items);
 SELECT * INTO prior FROM public.export_logs WHERE user_id=auth.uid() AND reservation_key=p_request_id;
 IF FOUND THEN
  IF prior.reservation_version IS DISTINCT FROM 'source-event-export-v1' OR prior.request_sha256 IS DISTINCT FROM req_hash
   OR prior.selection_sha256 IS DISTINCT FROM selection_hash THEN
   RAISE EXCEPTION 'Export request identity conflicts with an existing receipt' USING ERRCODE='22023';END IF;
  RETURN jsonb_build_object('status','replayed','request_id',p_request_id,'row_count',prior.row_count,
   'event_count',cardinality(a.record_keys),'property_ids',prior.authorized_property_ids,'rows',prior.receipt_payload,
   'entitlement',prior.entitlement_receipt);
 END IF;
 rows:=snap_relaunch.source_detail_rows_v1(a.id);n:=jsonb_array_length(rows);
 SELECT array_agg((value->>'property_id')::uuid ORDER BY value->>'property_id') INTO ids FROM jsonb_array_elements(rows);
 IF n NOT BETWEEN 1 AND 1000 OR n<>cardinality(a.mapping_ids) OR octet_length(rows::text)>6291456
  OR (SELECT sum(jsonb_array_length(value->'events')) FROM jsonb_array_elements(rows))<>cardinality(a.record_keys) THEN
  RAISE EXCEPTION 'Source detail export incomplete or oversized' USING ERRCODE='42501';END IF;
 IF mode='subscription' THEN
  result:=public.fn_consume_usage_atomic('exports',n);
  IF (result->>'allowed')::boolean IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'Export quota authorization failed' USING ERRCODE='P0001',DETAIL=result::text;END IF;
  entitlement:=jsonb_build_object('mode',mode,'usage',result);
  INSERT INTO public.unlocked_properties(user_id,property_id,credit_cost,unlock_source)
   SELECT auth.uid(),id,0,'subscription' FROM unnest(ids) id ON CONFLICT(user_id,property_id) DO NOTHING;
 ELSIF mode='trial' THEN
  result:=public.fn_increment_trial_exports(auth.uid(),n);
  IF (result->>'success')::boolean IS DISTINCT FROM true THEN
   RAISE EXCEPTION 'Trial export quota authorization failed' USING ERRCODE='P0001',DETAIL=result::text;END IF;
  entitlement:=jsonb_build_object('mode',mode,'usage',result);
  INSERT INTO public.unlocked_properties(user_id,property_id,credit_cost,unlock_source)
   SELECT auth.uid(),id,0,'subscription' FROM unnest(ids) id ON CONFLICT(user_id,property_id) DO NOTHING;
 ELSE
  FOREACH pid IN ARRAY ids LOOP
   result:=public.fn_unlock_property(auth.uid(),pid);
   IF (result->>'success')::boolean IS DISTINCT FROM true THEN
    RAISE EXCEPTION 'Export property authorization failed' USING ERRCODE='P0001',DETAIL=result::text;END IF;
   unlocks:=unlocks||jsonb_build_array(jsonb_build_object('property_id',pid,'receipt',result));
  END LOOP;
  entitlement:=jsonb_build_object('mode',mode,'unlocks',unlocks);
 END IF;
 entitlement:=entitlement||jsonb_build_object('acceptance_id',a.id,'acceptance_revision',a.command_sha256,
  'preparation_sha256',a.preparation_sha256,'selection_sha256',a.selection_sha256,'mapping_ids',a.mapping_ids,
  'event_count',cardinality(a.record_keys),'billing_unit','property','scope',a.scope);
 INSERT INTO public.export_logs(user_id,row_count,filters,reservation_key,reservation_version,request_sha256,
  selection_sha256,authorized_property_ids,receipt_payload,entitlement_receipt)
 VALUES(auth.uid(),n,jsonb_build_object('authorization','source-event-export-v1'),p_request_id,'source-event-export-v1',
  req_hash,selection_hash,ids,rows,entitlement);
 RETURN jsonb_build_object('status','reserved','request_id',p_request_id,'row_count',n,'event_count',cardinality(a.record_keys),
  'property_ids',ids,'rows',rows,'entitlement',entitlement);
END $function$
;
-- END EXACT CORE
DO $after$ DECLARE observed jsonb;snapshot jsonb;t text;n bigint; BEGIN
 IF current_user<>'postgres' OR current_setting('transaction_isolation')<>'read committed' OR current_setting('session_replication_role')<>'origin' THEN RAISE EXCEPTION 'source_consumer_install_session';END IF;
 -- Match the captured catalog rendering; pg_catalog remains implicitly first.
 PERFORM set_config('search_path','public',true);
 SELECT jsonb_build_object(
'functions',(SELECT jsonb_agg(jsonb_build_object('signature',n.nspname||'.'||p.proname||'('||oidvectortypes(p.proargtypes)||')','definition_md5',md5(pg_get_functiondef(p.oid)),'owner',pg_get_userbyid(p.proowner),'acl',p.proacl::text,'security_definer',p.prosecdef,'config',p.proconfig) ORDER BY n.nspname,p.proname,oidvectortypes(p.proargtypes)) FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname IN('public','snap_relaunch') AND p.proname IN('fn_unlock_property','require_source_acceptance_v1','owner_source_acceptance_status_v1','source_management_current_grant_v1','source_accepting_authority_current_v1','fn_source_property_visible_v1','fn_is_source_property_v1','fn_increment_trial_exports','fn_reserve_export_v1','fn_reserve_source_export_v1','fn_get_source_crm_detail_v1','fn_handoff_source_to_crm_v1','source_hash_v1','source_manifest_v1','source_authorization_current_v1','has_role')),
'tables',(SELECT jsonb_agg(jsonb_build_object('table',n.nspname||'.'||c.relname,'owner',pg_get_userbyid(c.relowner),'acl',c.relacl::text,'rls',c.relrowsecurity,'force_rls',c.relforcerowsecurity,'policies',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',p.polname,'permissive',p.polpermissive,'command',p.polcmd,'roles',(SELECT jsonb_agg(CASE WHEN x=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x) END ORDER BY CASE WHEN x=0 THEN 'PUBLIC' ELSE pg_get_userbyid(x) END) FROM unnest(p.polroles) x),'using',pg_get_expr(p.polqual,p.polrelid),'check',pg_get_expr(p.polwithcheck,p.polrelid)) ORDER BY p.polname),'[]'::jsonb) FROM pg_policy p WHERE p.polrelid=c.oid),'triggers',(SELECT coalesce(jsonb_agg(jsonb_build_object('name',t.tgname,'enabled',t.tgenabled,'definition',pg_get_triggerdef(t.oid,true)) ORDER BY t.tgname),'[]'::jsonb) FROM pg_trigger t WHERE t.tgrelid=c.oid AND NOT t.tgisinternal)) ORDER BY n.nspname,c.relname) FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE c.relkind='r' AND (n.nspname='snap_relaunch' OR (n.nspname='public' AND c.relname IN('profiles','properties','unlocked_properties','user_subscriptions','subscription_plans','credit_ledger','leads','lead_activities','pipeline_stages')))),
'defaults',(SELECT coalesce(jsonb_agg(jsonb_build_object('role',pg_get_userbyid(d.defaclrole),'schema',coalesce(n.nspname,''),'kind',d.defaclobjtype,'acl',d.defaclacl::text) ORDER BY d.defaclrole,coalesce(n.nspname,''),d.defaclobjtype),'[]'::jsonb) FROM pg_default_acl d LEFT JOIN pg_namespace n ON n.oid=d.defaclnamespace WHERE d.defaclrole=(SELECT oid FROM pg_roles WHERE rolname='postgres') AND (d.defaclnamespace=0 OR n.nspname IN('public','snap_relaunch'))),
'helper_absent',to_regprocedure('snap_relaunch.source_self_consumer_eligible_v1(uuid)') IS NULL
) INTO observed;
 IF observed IS DISTINCT FROM '{"defaults":[{"acl":"{postgres=rwU/postgres,anon=rwU/postgres,authenticated=rwU/postgres,service_role=rwU/postgres,sandbox_exec_ojyxblegxpdgaqiscxpz=rU/postgres,sandbox_exec=rU/postgres}","kind":"S","role":"postgres","schema":"public"},{"acl":"{postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres,sandbox_exec_ojyxblegxpdgaqiscxpz=X/postgres}","kind":"f","role":"postgres","schema":"public"},{"acl":"{postgres=arwdDxtm/postgres,anon=arwdDxtm/postgres,authenticated=arwdDxtm/postgres,service_role=arwdDxtm/postgres,sandbox_exec_ojyxblegxpdgaqiscxpz=ar/postgres,sandbox_exec=ar/postgres}","kind":"r","role":"postgres","schema":"public"}],"functions":[{"acl":"{postgres=X/postgres,authenticated=X/postgres,sandbox_exec_ojyxblegxpdgaqiscxpz=X/postgres}","config":["search_path=pg_catalog"],"definition_md5":"a1eea5eeec848373e3993ebb121d2d9b","owner":"postgres","security_definer":true,"signature":"public.fn_get_source_crm_detail_v1(uuid)"},{"acl":"{postgres=X/postgres,authenticated=X/postgres,sandbox_exec_ojyxblegxpdgaqiscxpz=X/postgres}","config":["search_path=pg_catalog"],"definition_md5":"85dc86f773ec883927dd66e5445245f7","owner":"postgres","security_definer":true,"signature":"public.fn_handoff_source_to_crm_v1(uuid, uuid, uuid, uuid)"},{"acl":"{postgres=X/postgres,service_role=X/postgres,sandbox_exec_ojyxblegxpdgaqiscxpz=X/postgres,authenticated=X/postgres}","config":["search_path=public"],"definition_md5":"2a549cdcab2d81d9435ac6b1ff688c07","owner":"postgres","security_definer":true,"signature":"public.fn_increment_trial_exports(uuid, integer)"},{"acl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres,sandbox_exec_ojyxblegxpdgaqiscxpz=X/postgres}","config":["search_path=pg_catalog"],"definition_md5":"2f48847d24624b79daf6ea504c48d184","owner":"postgres","security_definer":true,"signature":"public.fn_is_source_property_v1(uuid)"},{"acl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres,sandbox_exec_ojyxblegxpdgaqiscxpz=X/postgres}","config":["search_path=public"],"definition_md5":"3916c08e35aa36a66f9a8de4c6560a92","owner":"postgres","security_definer":true,"signature":"public.fn_reserve_export_v1(uuid, text, uuid[], boolean)"},{"acl":"{postgres=X/postgres,authenticated=X/postgres,sandbox_exec_ojyxblegxpdgaqiscxpz=X/postgres}","config":["search_path=pg_catalog"],"definition_md5":"a9a0032a96110bf3f2babd637ad74465","owner":"postgres","security_definer":true,"signature":"public.fn_reserve_source_export_v1(uuid, uuid)"},{"acl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres,sandbox_exec_ojyxblegxpdgaqiscxpz=X/postgres}","config":["search_path=pg_catalog"],"definition_md5":"725f9ec0849473cb7d86570a2a66bb13","owner":"postgres","security_definer":true,"signature":"public.fn_source_property_visible_v1(uuid)"},{"acl":"{postgres=X/postgres,authenticated=X/postgres,service_role=X/postgres,sandbox_exec_ojyxblegxpdgaqiscxpz=X/postgres}","config":["search_path=public"],"definition_md5":"95b40381979d3ac216ec289e756326e7","owner":"postgres","security_definer":true,"signature":"public.fn_unlock_property(uuid, uuid)"},{"acl":"{=X/postgres,postgres=X/postgres,anon=X/postgres,authenticated=X/postgres,service_role=X/postgres,sandbox_exec_ojyxblegxpdgaqiscxpz=X/postgres}","config":["search_path=pg_catalog"],"definition_md5":"656bbe89910abf10ea08b61e2f72e087","owner":"postgres","security_definer":false,"signature":"public.has_role(uuid, app_role)"},{"acl":"{postgres=X/postgres}","config":["search_path=pg_catalog"],"definition_md5":"2f31dbf3ecd85bb64790d60da15a450a","owner":"postgres","security_definer":true,"signature":"snap_relaunch.owner_source_acceptance_status_v1(text, uuid)"},{"acl":"{postgres=X/postgres}","config":["search_path=pg_catalog"],"definition_md5":"50fd322fdf1bfb831510c7e06d681042","owner":"postgres","security_definer":true,"signature":"snap_relaunch.require_source_acceptance_v1(uuid, text)"},{"acl":"{postgres=X/postgres}"